Action: plot_chart({'chart_type': 'bar', 'query': "WITH per_inspection AS ( SELECT i.inspection_id, i.inspection_score, SUM(CASE WHEN vc.critical THEN COALESCE(v.violation_occurrences, 1) ELSE 0 END) AS critical_occurrences, SUM(CASE WHEN vc.critical = FALSE THEN COALESCE(v.violation_occurrences, 1) ELSE 0 END) AS noncritical_occurrences FROM inspections i LEFT JOIN violations v ON i.inspection_id = v.inspection_id LEFT JOIN violation_codes vc ON vc.violation_code_id = v.violation_code_id GROUP BY i.inspection_id, i.inspection_score ) SELECT CASE WHEN critical_occurrences > 0 AND noncritical_occurrences > 0 THEN 'Both types cited' WHEN critical_occurrences > 0 THEN 'Critical only' WHEN noncritical_occurrences > 0 THEN 'Non-critical only' ELSE 'No cited violations' END AS citation_group, ROUND(AVG(inspection_score), 1) AS average_inspection_score FROM per_inspection GROUP BY citation_group ORDER BY average_inspection_score DESC", 'title': 'Average inspection score by cited violation type', 'x': 'citation_group', 'y': 'average_inspection_score'})

